export class ApiError extends Error {
  constructor(status, message, body = null) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.body = body;
  }
}

async function readResponseBody(response) {
  const contentType = response.headers.get("content-type") ?? "";

  if (response.status === 204) {
    return null;
  }

  if (contentType.includes("application/json")) {
    return response.json();
  }

  return response.text();
}

export async function requestJson(path, { signal } = {}) {
  const response = await fetch(path, { signal });
  const body = await readResponseBody(response);

  if (!response.ok) {
    const message =
      body && typeof body === "object" && "error" in body
        ? String(body.error)
        : `Request failed: ${response.status}`;

    throw new ApiError(response.status, message, body);
  }

  return body;
}

async function findOrCreateByField(Model, field, value, defaults = {}) {
  return Model.findOrCreate({
    where: { [field]: value },
    defaults: { [field]: value, ...defaults },
  });
}

async function createRecordsIfEmpty(Model, where, records) {
  const count = await Model.count({ where });
  if (count === 0) {
    await Model.bulkCreate(records);
  }
}

module.exports = {
  findOrCreateByField,
  createRecordsIfEmpty,
};

