const { Model } = require("sequelize");

class SerializableModel extends Model {
  toJSON() {
    const data = { ...this.get() };
    const hiddenFields = this.constructor.hiddenFields ?? [];

    for (const field of hiddenFields) {
      delete data[field];
    }

    return data;
  }
}

function createModel({
  sequelize,
  modelName,
  attributes,
  hiddenFields = [],
  associate,
}) {
  class DefinedModel extends SerializableModel {}

  DefinedModel.modelName = modelName;
  DefinedModel.hiddenFields = hiddenFields;

  if (typeof associate === "function") {
    DefinedModel.associate = associate;
  }

  DefinedModel.init(attributes, { sequelize, modelName });

  return DefinedModel;
}

module.exports = { SerializableModel, createModel };

